"""Neon Racer cars from Tripo3D GLBs (generated by skink52): decimated once into assets/neon/<key>.npz + <key>.png
(about 9k triangles and a 1024 texture each), then turned into CS2 models here. Each car is unlit (the whole map is),
its glowing strips are recoloured per skin (T / CT shades, gold), and boost / pad flames are animated planes.

python3 tools/neoncars.py import <dir with the GLBs>     (car 1..4, pylon 2, flight gate: re-decimates into assets/neon)
"""
import os, sys, colorsys
import numpy as np
from PIL import Image
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import s2, glbmesh

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ADIR = os.path.join(ROOT, 'assets', 'neon')
SOURCES = {'hornet': 'car 1', 'meteor': 'car 2', 'comet': 'car 3', 'bastion': 'car 4'}
LENGTH = {'hornet': 118, 'meteor': 126, 'comet': 124, 'bastion': 122}
TRIS = 9000

def import_glbs(src):
    os.makedirs(ADIR, exist_ok=True)
    for key, f in SOURCES.items():
        V, UV, F, tex = glbmesh.load(os.path.join(src, f + '.glb'))
        V = np.c_[V[:, 0], -V[:, 2], V[:, 1]]               # glTF Y-up -> Z-up (the nose ends up at -y)
        V = np.c_[-V[:, 1], V[:, 0], V[:, 2]]               # nose to +x (CS2 forward)
        V, UV, F = glbmesh.weld(V, UV, F)
        V, UV, F = glbmesh.decimate_to(V, UV, F, TRIS)
        np.savez_compressed(os.path.join(ADIR, key + '.npz'), V=V.astype(np.float32), UV=UV.astype(np.float32), F=F.astype(np.int32))
        tex.resize((1024, 1024), Image.LANCZOS).save(os.path.join(ADIR, key + '.png'), optimize=True)
        print(key, len(F), 'triangles')

PROPS = {'pylon': ('pylon 2', 700), 'gate': ('flight gate', 1400)}

def import_props(src):
    for key, (f, n) in PROPS.items():
        V, UV, F, tex = glbmesh.load(os.path.join(src, f + '.glb'))
        V = np.c_[V[:, 0], -V[:, 2], V[:, 1]]
        V, UV, F = glbmesh.weld(V, UV, F)
        V, UV, F = glbmesh.decimate_to(V, UV, F, n)
        np.savez_compressed(os.path.join(ADIR, key + '.npz'), V=V.astype(np.float32), UV=UV.astype(np.float32), F=F.astype(np.int32))
        tex.resize((1024, 1024), Image.LANCZOS).save(os.path.join(ADIR, key + '.png'), optimize=True)
        print(key, len(F), 'triangles')

_PROP = {}
def prop(key):
    """a track prop (pylon, gate): V in its own units (base at z 0, centred), UV, F, texture path"""
    if key not in _PROP:
        z = np.load(os.path.join(ADIR, key + '.npz'))
        V = z['V'].astype(np.float64)
        V -= np.array([(V[:, 0].max() + V[:, 0].min()) / 2, (V[:, 1].max() + V[:, 1].min()) / 2, V[:, 2].min()])
        _PROP[key] = (V, z['UV'].astype(np.float64), z['F'].astype(np.int64), os.path.join(ADIR, key + '.png'))
    return _PROP[key]

def prop_tris(key, mat, at, sx, sy, sz, yaw=0.0):
    """the prop scaled (sx across, sy deep, sz up), turned by yaw (radians) and placed with its base at `at`"""
    V, UV, F, _ = prop(key)
    c, s_ = np.cos(yaw), np.sin(yaw)
    P = V * np.array([sx, sy, sz])
    P = np.c_[P[:, 0] * c - P[:, 1] * s_, P[:, 0] * s_ + P[:, 1] * c, P[:, 2]] + np.array(at)
    a, b, cc = P[F[:, 0]], P[F[:, 1]], P[F[:, 2]]
    n = np.cross(b - a, cc - a); n /= np.maximum(np.linalg.norm(n, axis=1), 1e-9)[:, None]
    out = []
    for k, (i, j, l) in enumerate(F):
        out.append((mat, tuple(tuple(P[x]) + (float(UV[x, 0]), float(1 - UV[x, 1])) for x in (i, j, l)), tuple(n[k])))
    return out

def load(key):
    z = np.load(os.path.join(ADIR, key + '.npz'))
    V = z['V'].astype(np.float64); UV = z['UV'].astype(np.float64); F = z['F'].astype(np.int64)
    ext = V.max(0) - V.min(0)
    s = LENGTH[key] / ext[0]
    V = (V - np.array([(V.max(0)[0] + V.min(0)[0]) / 2, (V.max(0)[1] + V.min(0)[1]) / 2, V.min(0)[2]])) * s
    return V, UV, F, Image.open(os.path.join(ADIR, key + '.png')).convert('RGB')

def recolour(img, rgb):
    """the glowing strips (bright, saturated, cyan-ish) take the skin's colour; everything else stays"""
    a = np.asarray(img, np.float32) / 255
    mx = a.max(2); mn = a.min(2); sat = (mx - mn) / np.maximum(mx, 1e-6)
    hsv = np.array([colorsys.rgb_to_hsv(*rgb[:3])]) if False else None
    glow = np.clip((sat - 0.35) / 0.3, 0, 1) * np.clip((mx - 0.35) / 0.3, 0, 1)
    tgt = np.array(rgb, np.float32) / 255
    lum = mx[..., None]
    hull = np.clip(a * 1.35 + tgt * 0.05, 0, 1)            # the dark hull a little lighter (unlit on a black road)
    out = hull * (1 - glow[..., None]) + np.clip(tgt * lum / max(tgt.max(), 1e-6) * 1.05, 0, 1) * glow[..., None]
    return (np.clip(out, 0, 1) * 255).astype(np.uint8)

def flame_texture(cols, frames=4, W=64, H=32):
    """frames side by side: a flame along +u (nozzle at u=0), white core, the style's colours outward, flickering"""
    img = np.zeros((H, W * frames, 3), np.float32); alpha = np.zeros((H, W * frames), np.float32)
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    v = np.abs(yy - (H - 1) / 2) / (H / 2); u = xx / W
    for f in range(frames):
        wob = 0.85 + 0.15 * np.sin(u * 18 + f * 1.7)
        width = (1 - u) ** 0.8 * wob
        core = np.clip(1 - v / np.maximum(width * 0.45, 1e-3), 0, 1)
        body = np.clip(1 - v / np.maximum(width, 1e-3), 0, 1)
        c = np.zeros((H, W, 3), np.float32)
        c += np.array(cols[1], np.float32) * body[..., None]
        c += (np.array(cols[-1], np.float32) - np.array(cols[1], np.float32)) * core[..., None]
        img[:, f * W:(f + 1) * W] = c
        alpha[:, f * W:(f + 1) * W] = np.clip(body * 1.6, 0, 1) * np.clip((1 - u) * 1.5, 0, 1)
    return np.clip(img, 0, 255).astype(np.uint8), (alpha * 255).astype(np.uint8)

def flame_tris(x0, z0, length, r, mat='spr_flame'):
    """two crossed planes behind the nozzle at (x0, 0, z0), pointing back (-x)"""
    t = []
    for ax in ((0, 1, 0), (0, 0, 1)):
        a = (x0, -r * ax[1], z0 - r * ax[2], 0, 1); b = (x0 - length, -r * ax[1], z0 - r * ax[2], 1, 1)
        c = (x0 - length, r * ax[1], z0 + r * ax[2], 1, 0); d = (x0, r * ax[1], z0 + r * ax[2], 0, 0)
        n = (0, -ax[2], ax[1])
        t += [(mat, (a, b, c), n), (mat, (a, c, d), n)]
    return t

def car_tris(V, UV, F, hover):
    a, b, c = V[F[:, 0]], V[F[:, 1]], V[F[:, 2]]
    n = np.cross(b - a, c - a); n /= np.maximum(np.linalg.norm(n, axis=1), 1e-9)[:, None]
    tris = []
    for k, (i, j, l) in enumerate(F):
        P = [tuple(V[x] + (0, 0, hover)) + (float(UV[x, 0]), float(1 - UV[x, 1])) for x in (i, j, l)]
        tris.append(('spr_body', tuple(P), tuple(n[k])))
    return tris

def build(out, mdir, pal_dir, key, skins, skin_order, flame_styles, hover, shadow_mat):
    """the car's three models (base, boost, pad); returns {'base': path, 'boost': path, 'pad': path}, the preview image source"""
    V, UV, F, tex = load(key)
    base_mat = s2.write_material(out, '%s/neon_%s' % (pal_dir, key), recolour(tex, (0, 235, 255)), comment='Neon Racer %s (neutral)' % key)
    skin_mats = {}
    for name in skin_order:
        skin_mats[name] = s2.write_material(out, '%s/neon_%s_%s' % (pal_dir, key, name), recolour(tex, skins[name][0]), comment='Neon Racer %s %s' % (key, name))
    body = car_tris(V, UV, F, hover)
    L = V[:, 0].max() - V[:, 0].min(); W = V[:, 1].max() - V[:, 1].min()
    hx, hy = L * 0.5, W * 0.5
    sh = [('spr_shadow', ((-hx, -hy, 0.6, 0, 1), (hx, -hy, 0.6, 1, 1), (hx, hy, 0.6, 1, 0)), (0, 0, 1)),
          ('spr_shadow', ((-hx, -hy, 0.6, 0, 1), (hx, hy, 0.6, 1, 0), (-hx, hy, 0.6, 0, 0)), (0, 0, 1))]
    rear = V[V[:, 0] < V[:, 0].min() + L * 0.08]
    nz = float(np.median(rear[:, 2])) + hover; nx = float(V[:, 0].min()) + 2
    rr = max(8.0, float(np.percentile(np.abs(rear[:, 2] - np.median(rear[:, 2])), 70)))
    paths = {}
    for kind in ('base', 'boost', 'pad'):
        tris = list(body) + sh
        mats = {'spr_body': base_mat, 'spr_shadow': shadow_mat}
        if kind != 'base':
            tris += flame_tris(nx, nz, 70 if kind == 'boost' else 100, rr * (1.0 if kind == 'boost' else 1.25))
            mats['spr_flame'] = flame_styles['pad' if kind == 'pad' else key]
        sk = [(name, [(base_mat, skin_mats[name])]) for name in skin_order]
        paths[kind] = s2.write_model(out, mdir, key + ('' if kind == 'base' else '_' + kind), tris, mats, sk)
    return paths

def flame_materials(out, pal_dir, styles):
    mats = {}
    for style, cols in styles.items():
        img, a = flame_texture(cols)
        mats[style] = s2.write_material(out, '%s/neon_flame_%s' % (pal_dir, style), img, a, blend=1, backfaces=True,
                                        comment='Neon Racer flame ' + style,
                                        extra=('F_TEXTURE_ANIMATION 1', 'g_nNumAnimationCells "4"', 'g_vAnimationGrid "[4.000000 1.000000]"',
                                               'g_flAnimationTimePerFrame "0.050"'))
    return mats

def picture(key, rgb, size, az=205, el=22, skin=None):
    """an RGBA render of the car from behind and to one side, like the race camera sees it"""
    V, UV, F, tex = load(key)
    tex = Image.fromarray(recolour(tex, rgb if rgb is not None else (0, 235, 255)))
    c = (V.max(0) + V.min(0)) / 2; L = (V.max(0) - V.min(0)).max()
    a, e = np.radians(az), np.radians(el)
    eye = c + np.array([np.cos(a) * np.cos(e), np.sin(a) * np.cos(e), np.sin(e)]) * L * 2.1
    im = glbmesh.render(V, UV, F, tex, eye, c, W=size, H=size, fov=32, bg=(255, 0, 255))
    a_ = np.array(im); m = (a_[..., 0] == 255) & (a_[..., 1] == 0) & (a_[..., 2] == 255)
    rgba = np.dstack([a_, np.where(m, 0, 255).astype(np.uint8)])
    return Image.fromarray(rgba, 'RGBA')

if __name__ == '__main__':
    if len(sys.argv) > 2 and sys.argv[1] == 'import': import_glbs(sys.argv[2]); import_props(sys.argv[2])
    elif len(sys.argv) > 2 and sys.argv[1] == 'props': import_props(sys.argv[2])
    else: sys.exit(__doc__)
